"""
DeepSeek Price Clock — שעון מחירי טוקנים של DeepSeek לפי שעון ישראל.
Portable Windows EXE (PyInstaller --onefile --windowed).

מחירים: עדכון אוטומטי מול האתר הרשמי של DeepSeek (api-docs.deepseek.com).
אסטרטגיית עדכון: sitemap -> דף המחירים -> אימות נתונים -> תמונת מצב מובנית כגיבוי.
שיא (מחיר מלא): 01:00-04:00 ו-06:00-10:00 UTC, ימי חול בלבד (שני-שישי).
כל השאר (כולל סופי שבוע) = שפל (מחיר מוזל).
"""
import datetime as dt
import html as html_mod
import queue
import re
import threading
import urllib.request
from zoneinfo import ZoneInfo

