def _lerp_hex(c1, c2, t):
    """ערבוב צבעי hex: מחזיר צבע אמצע בין c1 ל-c2 (0..1)."""
    a = [int(c1[i:i + 2], 16) for i in (1, 3, 5)]
    b = [int(c2[i:i + 2], 16) for i in (1, 3, 5)]
    return "#" + "".join(f"{int(x + (y - x) * t):02x}" for x, y in zip(a, b))


def detect_lang():
    try:
        # 0x040D = Hebrew (Israel); מחזיר את שפת ה-UI של Windows
        if (ctypes.windll.kernel32.GetUserDefaultUILanguage() & 0xFFFF) == 0x040D:
            return "he"
    except Exception:
        pass
    return "en"


def _pref_path():
    base = os.environ.get("LOCALAPPDATA") or os.path.expanduser("~")
    d = os.path.join(base, "DeepSeekPriceClock")
    try:
        os.makedirs(d, exist_ok=True)
    except Exception:
        pass
    return os.path.join(d, "prefs.json")


def load_prefs():
    prefs = {"lang": detect_lang(), "mode": "analog"}  # ברירת מחדל: שעון אנלוגי
    try:
        with open(_pref_path(), encoding="utf-8") as f:
            data = json.load(f)
        if data.get("lang") in STRINGS:
            prefs["lang"] = data["lang"]
        if data.get("mode") in ("digital", "analog"):
            prefs["mode"] = data["mode"]
    except Exception:
        pass
    return prefs


def save_prefs(prefs):
    try:
        with open(_pref_path(), "w", encoding="utf-8") as f:
            json.dump(prefs, f)
    except Exception:
        pass


class App:
    def __init__(self, root: tk.Tk):
        self.root = root
        self.q = queue.Queue()
        self.fetching = False
        self.top_var = tk.BooleanVar(value=False)
        prefs = load_prefs()
        self.lang = prefs["lang"]
        self.mode = prefs["mode"]
        self.S = STRINGS[self.lang]
        self._cache = {}
        self._celltext = {}
        self._shown_peak = None
        self._tr = None
        self._anim_running = False
        self._hands = {}
        self.face_img = None
        self.status = (self.S["upd_init"].format(date=SNAPSHOT_DATE), MUT)
        root.configure(bg=BG)
        self._build()
        self._start_fetch()
        self._tick()

    # ------------------------------------------------------------------
    def _toggle_lang(self):
        self.lang = "he" if self.lang == "en" else "en"
        save_prefs({"lang": self.lang, "mode": self.mode})
        self.S = STRINGS[self.lang]
        self._build()
        self._refresh()

    def _toggle_mode(self):
        self.mode = "analog" if self.mode == "digital" else "digital"
        save_prefs({"lang": self.lang, "mode": self.mode})
        self._build()
        self._refresh()

    def _toggle_top(self):
        self.root.attributes("-topmost", self.top_var.get())

    def _set(self, key, widget, text, **kw):
        if key in self._cache:
            prev, prevkw = self._cache[key]
            if prev == text and prevkw == kw:
                return
        widget.configure(text=text, **kw)
        self._cache[key] = (text, kw)

    def _build(self):
        for w in self.root.winfo_children():
            w.destroy()
        self._cache = {}      # התוויות נבנו מחדש - לאפס את מטמון הטקסטים
        self._celltext = {}   # וגם מטמון תאי המחיר (אחרת הם נשארים ריקים!)
        self.root.title(self.S["title"])
        S = self.S
        r = self.root

        # שעון: דיגיטלי גדול או אנלוגי (לפי ההעדפה)
        f_head = tk.Frame(r, bg=BG)
        f_head.pack(fill="x", padx=18, pady=(10, 2))
        self.time_lbl = tk.Label(f_head, font=("Segoe UI", 40, "bold"), fg=WHITE, bg=BG)
        self.clock_cv = tk.Canvas(f_head, width=180, height=180, bg=BG,
                                  highlightthickness=0)
        if self.mode == "analog":
            self.clock_cv.pack()
            self._init_analog_items()
        else:
            self.time_lbl.pack()
        self.date_lbl = tk.Label(f_head, font=("Segoe UI", 12), fg=MUT, bg=BG)
        self.date_lbl.pack(pady=(4, 0))
        self.zone_lbl = tk.Label(f_head, font=("Segoe UI", 9), fg=ACCENT, bg=BG)
        self.zone_lbl.pack()

        # כרטיס מצב מחיר
        self.card = tk.Frame(r, bg=CARD_OFF, highlightthickness=1, highlightbackground=BORDER)
        self.card.pack(fill="x", padx=18, pady=6)
        self.st_title = tk.Label(self.card, font=("Segoe UI", 17, "bold"), fg=GREEN, bg=CARD_OFF)
        self.st_title.pack(pady=(10, 0))
        self.st_sub = tk.Label(self.card, font=("Segoe UI", 10), fg=MUT, bg=CARD_OFF)
        self.st_sub.pack()
        self.st_next = tk.Label(self.card, font=("Segoe UI", 13, "bold"), fg=WHITE, bg=CARD_OFF)
        self.st_next.pack(pady=(2, 12))

        # השינויים הקרובים
        f_ev = tk.Frame(r, bg=BG)
        f_ev.pack(fill="x", padx=18, pady=(8, 2))
        tk.Label(f_ev, text=S["ev_head"], font=("Segoe UI", 11, "bold"),
                 fg=MUT, bg=BG).pack(anchor="e")
        self.ev_rows = []
        for _ in range(4):
            row = tk.Frame(f_ev, bg=BG)
            row.pack(fill="x", pady=1)
            dsc = tk.Label(row, font=("Segoe UI", 12), fg=WHITE, bg=BG, anchor="e")
            dsc.pack(side="right", fill="x", expand=True)
            tme = tk.Label(row, font=("Segoe UI", 12, "bold"), fg=ACCENT, bg=BG)
            tme.pack(side="right", padx=(10, 0))
            self.ev_rows.append((dsc, tme))

        # טבלת מחירים
        f_tab = tk.Frame(r, bg=BG)
        f_tab.pack(fill="x", padx=18, pady=(12, 2))
        tk.Label(f_tab, text=S["tab_caption"], font=("Segoe UI", 11, "bold"),
                 fg=MUT, bg=BG, justify="right").grid(row=0, column=0, columnspan=4,
                                                      sticky="e", pady=(0, 4))
        for c, htext in enumerate(("", S["h_hit"], S["h_miss"], S["h_out"])):
            tk.Label(f_tab, text=htext, font=("Segoe UI", 10, "bold"), fg=MUT,
                     bg=BG, justify="right").grid(row=1, column=c, padx=8, pady=2,
                                                  sticky="e" if c else "w")
        self.cells = {}
        for row_i, (api, data) in enumerate(MODEL_ROWS, start=2):
            tk.Label(f_tab, text=data["name"], font=("Segoe UI", 11, "bold"),
                     fg=WHITE, bg=BG, anchor="w").grid(row=row_i, column=0,
                                                       padx=(0, 14), pady=3, sticky="w")
            for c in range(1, 4):
                lab = tk.Label(f_tab, text="", font=("Consolas", 12, "bold"),
                               fg=GREEN, bg=BG, anchor="e", width=9)
                lab.grid(row=row_i, column=c, padx=8, sticky="e")
                self.cells[(row_i, c)] = lab
        tk.Label(f_tab, text=S["tab_note"], font=("Segoe UI", 9), fg=MUT, bg=BG,
                 justify="right", wraplength=520).grid(row=len(MODEL_ROWS) + 2,
                                                       column=0, columnspan=4,
                                                       pady=(6, 2), sticky="e")

        # שורת עדכון + מעבר שפה
        f_upd = tk.Frame(r, bg=BG)
        f_upd.pack(fill="x", padx=18, pady=(2, 2))
        self.btn_upd = tk.Button(f_upd, text=S["upd_btn"], command=self._manual_update,
                                 bg="#1c2330", fg=ACCENT, activebackground="#26304a",
                                 activeforeground=ACCENT, relief="flat",
                                 font=("Segoe UI", 9, "bold"), cursor="hand2",
                                 bd=0, padx=10, pady=3)
        self.btn_upd.pack(side="right")
        mode_lbl = S["btn_dig"] if self.mode == "analog" else S["btn_ana"]
        self.btn_mode = tk.Button(f_upd, text=mode_lbl, command=self._toggle_mode,
                                  bg="#1c2330", fg=WHITE, activebackground="#26304a",
                                  activeforeground=WHITE, relief="flat",
                                  font=("Segoe UI", 9, "bold"), cursor="hand2",
                                  bd=0, padx=10, pady=3)
        self.btn_mode.pack(side="right", padx=(0, 6))
        self.btn_lang = tk.Button(f_upd, text="עברית" if self.lang == "en" else "English",
                                  command=self._toggle_lang, bg="#1c2330", fg=GREEN,
                                  activebackground="#26304a", activeforeground=GREEN,
                                  relief="flat", font=("Segoe UI", 9, "bold"),
                                  cursor="hand2", bd=0, padx=10, pady=3)
        self.btn_lang.pack(side="right", padx=(0, 6))
        self.upd_lbl = tk.Label(f_upd, font=("Segoe UI", 9), fg=MUT, bg=BG,
                                anchor="e", justify="right")
        self.upd_lbl.pack(side="right", fill="x", expand=True, padx=(0, 8))

        # תחתית
        f_ftr = tk.Frame(r, bg=BG)
        f_ftr.pack(fill="x", padx=18, pady=(4, 12))
        self.note_lbl = tk.Label(f_ftr, font=("Segoe UI", 8), fg=MUT, bg=BG,
                                 justify="right", wraplength=540)
        self.note_lbl.pack(side="right", fill="x", expand=True)
        tk.Checkbutton(f_ftr, text=S["topmost"], variable=self.top_var,
                       command=self._toggle_top, bg=BG, fg=MUT, activebackground=BG,
                       activeforeground=MUT, selectcolor=BG, font=("Segoe UI", 9),
                       highlightthickness=0).pack(side="right", padx=(0, 14))
        # אייקון חלון
        try:
            self._icon = tk.PhotoImage(data=ICON_PNG)
            self.root.iconphoto(True, self._icon)
        except Exception:
            pass
        if self.mode == "analog":
            self._ensure_anim(True)
        self.root.geometry("")
        self.root.update_idletasks()

    # ------------------------------------------------------------------
    # עדכון מחירים אוטומטי
    def _start_fetch(self):
        if self.fetching:
            return
        self.fetching = True
        self.btn_upd.configure(state="disabled", text=self.S["upd_busy"])
        threading.Thread(target=self._worker, daemon=True).start()

    def _worker(self):
        try:
            found, windows, src = fetch_prices()
        except Exception as e:
            self.q.put(("err", str(e)))
            return
        if found:
            self.q.put(("ok", found, windows))
        else:
            self.q.put(("err", windows))

    def _manual_update(self):
        self._start_fetch()

    def _apply_fetch_result(self):
        kind = None
        while not self.q.empty():
            kind = self.q.get()
        if kind is None:
            return
        self.fetching = False
        self.btn_upd.configure(state="normal", text=self.S["upd_btn"])
        t = dt.datetime.now().strftime("%H:%M:%S")
        if kind[0] == "ok":
            _, found, windows = kind
            changed, win_changed = apply_prices(found, windows)
            if changed:
                txt = self.S["upd_ok_changed"].format(names=", ".join(changed), time=t)
            elif win_changed:
                txt = self.S["upd_ok_windows"].format(time=t)
            else:
                txt = self.S["upd_ok_same"].format(time=t)
            self.status = (txt, GREEN)
        else:
            reason = kind[1]
            if isinstance(reason, str):
                txt = self.S["upd_fail_err"].format(err=reason)
            else:
                txt = self.S["upd_fail_noprice"].format(date=SNAPSHOT_DATE, min=REFRESH_MIN)
            self.status = (txt, ERRC)
        self.root.after(REFRESH_MIN * 60 * 1000, self._start_fetch)

    # ------------------------------------------------------------------
    def _refresh(self):
        now_utc = dt.datetime.now(UTC)
        now_loc = now_utc.astimezone()
        peak = is_peak(now_utc)
        S = self.S

        if self.mode == "digital":
            self._set("t", self.time_lbl, now_loc.strftime("%H:%M:%S"))
        if self.lang == "he":
            date_txt = (f"יום {WDAY_HE[now_loc.weekday()]}, "
                        f"{now_loc.day} ב{MONTHS_HE[now_loc.month - 1]} {now_loc.year}")
        else:
            date_txt = (f"{WEEKDAY_EN[now_loc.weekday()]}, "
                        f"{MONTHS_EN[now_loc.month - 1]} {now_loc.day}, {now_loc.year}")
        self._set("d", self.date_lbl, date_txt)
        off = now_loc.utcoffset() or dt.timedelta(0)
        mins = int(off.total_seconds() // 60)
        sign = "+" if mins >= 0 else "-"
        mins = abs(mins)
        zname = now_loc.tzname() or "UTC"
        self._set("z", self.zone_lbl,
                  S["zone"].format(z=zname, o=f"UTC{sign}{mins // 60:02d}:{mins % 60:02d}"))

        title = S["state_on_t"] if peak else S["state_off_t"]
        sub = S["state_on_s"] if peak else S["state_off_s"]
        self._set("s_t", self.st_title, title)
        self._set("s_s", self.st_sub, sub)
        if self._shown_peak is None:
            self._shown_peak = peak
            pal = self._pal(peak)
            for w in (self.card, self.st_title, self.st_sub, self.st_next):
                w.configure(bg=pal["card_bg"])
            self.card.configure(highlightbackground=pal["hl"])
            if getattr(self, "_ring_item", None):
                self.clock_cv.itemconfigure(self._ring_item, outline=pal["hl"])
            self.st_title.configure(fg=pal["tfg"])
            for lab in self.cells.values():
                lab.configure(fg=pal["cbg"])
        elif peak != self._shown_peak:
            self._shown_peak = peak
            self._start_state_transition()

        nxt = next_change(now_utc)
        nxt_jer = nxt.astimezone()
        delta = fmt_delta((nxt - now_utc).total_seconds())
        if nxt_jer.date() == now_loc.date():
            when = S["today_at"].format(t=nxt_jer.strftime("%H:%M"))
        elif self.lang == "he":
            when = S["day_at"].format(wd=WDAY_HE[nxt_jer.weekday()],
                                      t=nxt_jer.strftime("%H:%M"))
        else:
            when = S["day_at"].format(wd=WEEKDAY_EN[nxt_jer.weekday()],
                                      t=nxt_jer.strftime("%H:%M"))
        nxt_txt = (S["next_drop"] if peak else S["next_rise"]).format(delta=delta, when=when)
        self._set("s_n", self.st_next, nxt_txt)

        starts = {w0 for w0, _ in PEAK_WINDOWS}
        for i, (dsc, tme) in enumerate(self.ev_rows):
            b = boundaries_after(now_utc, 4)[i]
            bj = b.astimezone()
            if bj.date() == now_loc.date():
                pref = ""
            elif self.lang == "he":
                pref = f"יום {WDAY_HE[bj.weekday()]} "
            else:
                pref = f"{WEEKDAY_EN[bj.weekday()]} "
            tme.configure(text=f"{pref}{bj.strftime('%H:%M')}")
            rising = b.hour in starts
            dsc.configure(text=S["ev_rise"] if rising else S["ev_fall"],
                          fg=AMBER if rising else GREEN)

        for row_i, (api, data) in enumerate(list(PRICES.items()), start=2):
            cur = data["peak"] if peak else data["off"]
            for c, v in enumerate(cur, start=1):
                key = (row_i, c)
                txt = f"${v:.3f}"
                if self._celltext.get(key) != txt:
                    self._celltext[key] = txt
                    self.cells[key].configure(text=txt)

        windows_txt = " & ".join(f"{s:02d}:00-{e:02d}:00" for s, e in PEAK_WINDOWS)
        if self.lang == "he":
            windows_txt = " ו-".join(f"{s:02d}:00–{e:02d}:00" for s, e in PEAK_WINDOWS)
        self._set("note", self.note_lbl, S["note"].format(w=windows_txt))
        self._set("upd", self.upd_lbl, self.status[0], fg=self.status[1])

    def _pal(self, peak):
        return {"card_bg": CARD_ON if peak else CARD_OFF,
                "hl": AMBER if peak else GREEN,
                "tfg": AMBER if peak else GREEN,
                "cbg": WHITE if peak else GREEN}

    def _init_analog_items(self):
        """פני השעון (תמונה מעובדת) + מחוגים - נוצרים פעם אחת ומחליקים ע"י coords."""
        cv = self.clock_cv
        try:
            self.face_img = tk.PhotoImage(data=FACE_PNG)
            cv.create_image(90, 90, image=self.face_img)
        except Exception:
            self.face_img = None
        # מסגרת צבעונית לפי מצב המחיר - מצוירת מעל הטבעת הכחולה החקוקה בתמונה
        self._ring_item = cv.create_oval(14, 14, 166, 166, outline=GREEN, width=15)
        self._hands = {
            "h": cv.create_line(90, 90, 90, 57, width=7, fill="#eef2ff",
                                capstyle="round"),
            "m": cv.create_line(90, 90, 90, 42, width=4, fill="#ffffff",
                                capstyle="round"),
            "s": cv.create_line(90, 90, 90, 42, width=2, fill=AMBER,
                                capstyle="round"),
        }
        cv.create_oval(85, 85, 95, 95, fill="#0c1322", outline="")
        cv.create_oval(88, 88, 92, 92, fill=AMBER, outline="")

    def _analog_now(self, now_loc):
        """עדכון קואורדינטות המחוגים - חלק, ללא מחיקת קנבס."""
        cv = self.clock_cv
        t = (now_loc.hour * 3600 + now_loc.minute * 60 + now_loc.second
             + now_loc.microsecond / 1e6)
        deg = {"h": (t / 3600 % 12) * 30,
               "m": (t / 60 % 60) * 6,
               "s": (t % 60) * 6}
        for key, length, tail in (("s", 62, 15), ("m", 48, 0), ("h", 33, 0)):
            a = math.radians(deg[key] - 90)
            ca, sa = math.cos(a), math.sin(a)
            x0 = 90 - tail * ca
            y0 = 90 - tail * sa
            cv.coords(self._hands[key], x0, y0, 90 + length * ca, 90 + length * sa)

    def _ensure_anim(self, on):
        if on and not self._anim_running:
            self._anim_running = True
            self.root.after(33, self._anim_loop)

    def _anim_loop(self):
        try:
            if self.mode == "analog":
                self._analog_now(dt.datetime.now().astimezone())
            if self._tr is not None:
                self._step_transition()
            keep = self.mode == "analog" or self._tr is not None
        except Exception:
            keep = False
        if keep:
            self.root.after(33, self._anim_loop)
        else:
            self._anim_running = False

    def _start_state_transition(self):
        """מעבר צבע חלק בין מצב שפל למצב שיא (ולהיפך)."""
        self._tr = {"t0": time.monotonic(), "dur": 0.6,
                    "src": self._pal(not self._shown_peak),
                    "tgt": self._pal(self._shown_peak)}
        self._ensure_anim(True)

    def _step_transition(self):
        t = min(1.0, (time.monotonic() - self._tr["t0"]) / self._tr["dur"])
        e = 1 - (1 - t) ** 3  # ease-out
        src, tgt = self._tr["src"], self._tr["tgt"]
        bg = _lerp_hex(src["card_bg"], tgt["card_bg"], e)
        hl = _lerp_hex(src["hl"], tgt["hl"], e)
        tf = _lerp_hex(src["tfg"], tgt["tfg"], e)
        cf = _lerp_hex(src["cbg"], tgt["cbg"], e)
        for w in (self.card, self.st_title, self.st_sub, self.st_next):
            w.configure(bg=bg)
        self.card.configure(highlightbackground=hl)
        if getattr(self, "_ring_item", None):
            self.clock_cv.itemconfigure(self._ring_item, outline=hl)
        self.st_title.configure(fg=tf)
        for lab in self.cells.values():
            lab.configure(fg=cf)
        if t >= 1:
            self._tr = None

    def _tick(self):
        self._apply_fetch_result()
        self._refresh()
        self.root.after(250, self._tick)


def main():
    root = tk.Tk()
    App(root)
    root.mainloop()


if __name__ == "__main__":
    main()
